def match(orders):
    import heapq

    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq'}
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                p, s, sid = sell_heap[0]
                if sid not in book or book[sid]['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if price is not None and p > price:
                    break
                trade_qty = min(remaining, book[sid]['qty'])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                book[sid]['qty'] -= trade_qty
                if book[sid]['qty'] == 0:
                    heapq.heappop(sell_heap)
                    del book[sid]

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                negp, s, bid = buy_heap[0]
                p = -negp
                if bid not in book or book[bid]['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if price is not None and p < price:
                    break
                trade_qty = min(remaining, book[bid]['qty'])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                book[bid]['qty'] -= trade_qty
                if book[bid]['qty'] == 0:
                    heapq.heappop(buy_heap)
                    del book[bid]

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

